(()=>{const out={},ns='http://www.w3.org/2000/svg',s=document.createElementNS(ns,'svg');document.body.append(s);const run=(key,fn)=>{try{const v=fn();out[key]=v===undefined?'undefined':v}catch(e){out[key]=e.name}},r=document.createElementNS(ns,'rect');r.setAttribute('width','10');r.setAttribute('height','20');s.append(r);for(const name of ['createSVGPoint','createSVGLength','createSVGMatrix','getBBox','getCTM'])run(name+'Brand',()=>s[name].call({}));for(const kind of ['Point','Length','Number','Matrix','Rect'])for(const [label,value]of [['nan',NaN],['inf',Infinity],['big',1n],['symbol',Symbol()],['string','2.5']])run(kind+label,()=>{const o=s['createSVG'+kind](),key=kind==='Point'||kind==='Rect'?'x':kind==='Matrix'?'a':'value';o[key]=value;return o[key]});const l=s.createSVGLength();run('wrapUnit',()=>{l.newValueSpecifiedUnits(65537,2);return [l.unitType,l.value]});run('missingUnit',()=>l.newValueSpecifiedUnits());run('badLength',()=>{l.valueAsString='bogus';return l.value});run('negativeRect',()=>{const b=s.createSVGRect();b.width=-2;return b.width});run('singular',()=>{const m=s.createSVGMatrix();m.a=0;m.inverse()});run('zeroVector',()=>s.createSVGMatrix().rotateFromVector(0,2));run('defaultFill',()=>r.isPointInFill());run('nullFill',()=>r.isPointInFill(null));run('getPointNaN',()=>r.getPointAtLength(NaN));run('getPointMissing',()=>r.getPointAtLength());const p=document.createElementNS(ns,'polyline');p.setAttribute('points','1 2 3 4');s.append(p);run('indexedKeys',()=>Object.keys(p.points));run('indexedReadonly',()=>{p.animatedPoints[0]=s.createSVGPoint();return p.animatedPoints[0].x});run('listBrand',()=>p.points.getItem.call({},0));run('listMissing',()=>p.points.getItem());run('listBigIndex',()=>p.points.getItem(1n));s.remove();return out})()